def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Endgame: exploit cooperative opponents, but avoid mutual defection against defectors.
    if n >= 100:
        return 'C'

    opp_c = sum(1 for a, b in history if b == 'C')
    my_c = sum(1 for a, b in history if a == 'C')
    opp_d = n - opp_c
    my_d = n - my_c

    if n >= 90:
        if opp_c >= n * 0.75:
            return 'D'
        if opp_c <= n * 0.25:
            return 'D'
        return 'D' if history[-1][1] == 'C' else 'C'

    if n >= 80:
        if opp_c >= n * 0.8:
            return 'D'
        if opp_c <= n * 0.2:
            return 'D'
        return 'C' if history[-1][1] == 'C' else 'D'

    last_opp = history[-1][1]

    # Very short opening: cooperate, but retaliate immediately.
    if n < 6:
        return 'C' if last_opp == 'C' else 'D'

    # Opponent has never defected: cooperate, with rare probing if we're behind.
    if opp_d == 0:
        if n > 25 and my_d == 0 and n % 13 == 0:
            if rng.random() < 0.35:
                return 'D'
        return 'C'

    # Opponent almost always defects: defect, with rare cooperation to test recovery.
    if opp_d >= n - 2:
        if rng.random() < 0.04:
            return 'C'
        return 'D'

    recent = history[-10:]
    recent_opp_c = sum(1 for a, b in recent if b == 'C')
    recent_opp_d = len(recent) - recent_opp_c
    my_recent_c = sum(1 for a, b in recent if a == 'C')

    # Strong recent defection: punish hard, but don't lock into endless DD.
    if recent_opp_d >= 8:
        if my_recent_c >= 7 and rng.random() < 0.12:
            return 'C'
        return 'D'

    # Opponent has been very cooperative recently: cooperate, with moderate exploitation
    # when we have been sufficiently cooperative and are not at risk of collapse.
    if recent_opp_c >= 9:
        if n > 30 and opp_c >= n * 0.85 and my_c >= n * 0.5:
            if rng.random() < 0.22:
                return 'D'
        return 'C'

    # Just got defected on: retaliate, but forgive if opponent is overall cooperative
    # and their defection is isolated.
    if last_opp == 'D':
        if n >= 2 and history[-2][1] == 'D':
            # Two defections in a row: stay defensive briefly.
            if n >= 3 and history[-3][1] == 'D':
                if opp_c >= n * 0.55:
                    return 'C'
                return 'D'
            return 'D'
        # Single defection against a mostly cooperative opponent: forgive often.
        if opp_c >= n * 0.7:
            if rng.random() < 0.75:
                return 'C'
        if opp_c >= n * 0.45:
            if rng.random() < 0.35:
                return 'C'
        return 'D'

    # Opponent cooperated last. Cooperate, but exploit heavily cooperative opponents
    # when we are not vulnerable.
    if opp_c >= n * 0.8 and n > 40:
        if my_c >= n * 0.65 and rng.random() < 0.28:
            return 'D'
        return 'C'

    # Against moderately cooperative opponents, mostly cooperate.
    if opp_c >= n * 0.5:
        if n % 17 == 16 and my_c > opp_c + 5:
            if rng.random() < 0.4:
                return 'D'
        return 'C'

    # Against moderately defective opponents, mix toward defection.
    if opp_d >= n * 0.5:
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    return 'C'
